import React, { ReactNode, ComponentPropsWithoutRef } from 'react';

// 1. Reusable typed button extending native HTML button attributes:
interface ButtonProps extends ComponentPropsWithoutRef<'button'> {
  variant?: 'primary' | 'secondary' | 'danger';
  size?: 'sm' | 'md' | 'lg';
  isLoading?: boolean;
  children: ReactNode; // Standard for children
}

export function Button({
  variant = 'primary',
  size = 'md',
  isLoading = false,
  disabled,
  children,
  ...restProps
}: ButtonProps) {
  return (
    <button
      className={`btn btn-${variant} btn-${size}`}
      disabled={disabled || isLoading}
      {...restProps}
    >
      {isLoading ? <span className="spinner" /> : children}
    </button>
  );
}

import { useState, useRef, useReducer, ChangeEvent, FormEvent } from 'react';

interface User {
  id: string;
  name: string;
  email: string;
}

export function UserRegistration() {
  // Explicit generic for nullable state:
  const [user, setUser] = useState<User | null>(null);

  // DOM ref strictly typed to HTMLInputElement:
  const nameInputRef = useRef<HTMLInputElement>(null);

  // Strongly typed synthetic event handlers:
  function handleInputChange(e: ChangeEvent<HTMLInputElement>) {
    console.log("Current input value:", e.target.value);
  }

  function handleFormSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (nameInputRef.current) {
      setUser({
        id: crypto.randomUUID(),
        name: nameInputRef.current.value,
        email: "user@enterprise.com"
      });
    }
  }

  return (
    <form onSubmit={handleFormSubmit}>
      <input ref={nameInputRef} onChange={handleInputChange} placeholder="Name" />
      <button type="submit">Save</button>
    </form>
  );
}

import React from 'react';

// 1. Discriminated Union Async State:
type RequestState<T> =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'success'; data: T }
  | { status: 'error'; message: string };

// 2. Generic Reusable Table Component:
interface Column<T> {
  key: keyof T | string;
  header: string;
  render?: (item: T) => React.ReactNode;
}

interface GenericTableProps<T> {
  data: T[];
  columns: Column<T>[];
  rowKey: (item: T) => string;
}

export function GenericTable<T>({ data, columns, rowKey }: GenericTableProps<T>) {
  return (
    <table className="enterprise-table">
      <thead>
        <tr>
          {columns.map((col, idx) => (
            <th key={idx}>{col.header}</th>
          ))}
        </tr>
      </thead>
      <tbody>
        {data.map(item => (
          <tr key={rowKey(item)}>
            {columns.map((col, idx) => (
              <td key={idx}>
                {col.render ? col.render(item) : String((item as Record<string, unknown>)[col.key as string] ?? '')}
              </td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

// Comparison: Fragile vs Robust Testing Approach
// 1. The Component under test:
function StatusIndicator({ isOnline }) {
  const [internalCode, setInternalCode] = useState(isOnline ? 200 : 503);
  return (
    <div role="status" aria-label="System Status">
      {isOnline ? 'System Operational' : 'System Degraded'}
    </div>
  );
}

// ❌ FRAGILE TEST (Tests internal state - breaks when internalCode is removed)
test('bad test', () => {
  const wrapper = shallow(<StatusIndicator isOnline={true} />);
  expect(wrapper.state('internalCode')).toBe(200); // ❌ Implementation leak!
});

// ✅ ROBUST RTL TEST (Tests what a user or screen reader sees)
import { render, screen } from '@testing-library/react';

test('renders operational status when isOnline is true', () => {
  render(<StatusIndicator isOnline={true} />);
  const statusElement = screen.getByRole('status', { name: /system status/i });
  expect(statusElement).toHaveTextContent(/system operational/i);
});

